        const font = parse(readFont('Vibur.woff'));

        expect(font.outlinesFormat).toBe('truetype');
        expect(font.unitsPerEm).toBe(2048);
        expect(font.ascender).toBe(1960);
        expect(font.descender).toBe(-792);
        expect(font.numGlyphs).toBe(249);
        expect(font.glyphs.length).toBe(249);

        // glyf is stored compressed, loca/maxp are stored uncompressed in this fixture.
        const glyph = font.glyphs.get(36);
        expect(glyph.name).toBe('A');
        expect(glyph.advanceWidth).toBe(1138);
        expect(glyph.path.commands.length).toBe(42);
        expect(glyph.getBoundingBox()).toEqual({x1: -97, y1: 0, x2: 979, y2: 1550});

        expect(Object.keys(font.kerningPairs).length).toBe(8822);
        expect(font.kerningPairs['5,15']).toBe(-202);
        expect(font.getKerningValue(font.glyphs.get(5), font.glyphs.get(15))).toBe(-202);
        expect(font.glyphs.get(5).name).toBe('quotedbl');
        expect(font.glyphs.get(15).name).toBe('comma');
    });

    test('decompresses a CFF flavored WOFF font', () => {
        const font = parse(readFont('FiraSansMedium.woff'));

        expect(font.outlinesFormat).toBe('cff');
        expect(font.tables.cff).toBeDefined();
        expect(font.names.windows.fontFamily.en).toBe('Fira Sans OT');
        expect(font.unitsPerEm).toBe(1000);
        expect(font.numGlyphs).toBe(1147);

        const glyph = font.charToGlyph('A');
        expect(glyph.index).toBe(36);
        expect(glyph.advanceWidth).toBe(579);
        expect(glyph.path.commands.length).toBe(14);
    });

    test('rejects a WOFF file with an unsupported outline flavor', () => {
        const buffer = Buffer.from(readFont('Vibur.woff'));
        buffer.write('xxxx', 4, 4, 'latin1');

        expect(() => parse(buffer)).toThrow(/^Unsupported OpenType flavor wOFF$/);
    });
});

describe('input buffer types', () => {
    test('accepts Node Buffers, Uint8Arrays and ArrayBuffers equivalently', () => {
        const buffer = readFont('Changa-Regular.ttf');
        const uint8 = new Uint8Array(buffer);
        const arrayBuffer = uint8.buffer.slice(uint8.byteOffset, uint8.byteOffset + uint8.byteLength);

        const fromBuffer = parse(buffer);
        const fromUint8 = parse(uint8);
        const fromArrayBuffer = parse(arrayBuffer);

        expect(fromBuffer.numGlyphs).toBe(790);
        expect(fromUint8.numGlyphs).toBe(fromBuffer.numGlyphs);
        expect(fromArrayBuffer.numGlyphs).toBe(fromBuffer.numGlyphs);
        expect(fromUint8.charToGlyphIndex('A')).toBe(fromBuffer.charToGlyphIndex('A'));
        expect(fromArrayBuffer.glyphs.get(4).path.commands.length).toBe(16);
    });

    test('copies a Uint8Array view that is offset inside a larger buffer', () => {
        const source = readFont('Changa-Regular.ttf');
        const padded = Buffer.concat([Buffer.alloc(11, 0xee), source, Buffer.alloc(5, 0xee)]);
        const view = new Uint8Array(padded.buffer, padded.byteOffset + 11, source.length);
        expect(view.byteOffset).not.toBe(0);

        const font = parse(view);
        expect(font.numGlyphs).toBe(790);
        expect(font.charToGlyph('A').name).toBe('A');
    });
});

describe('invalid input', () => {
    test('rejects an unknown sfnt signature', () => {
        const buffer = Buffer.from('ZZZZ some payload here', 'latin1');

        expect(() => parse(buffer)).toThrow('Unsupported OpenType signature ZZZZ');
    });

    test('rejects WOFF2 data with an actionable message', () => {
        const buffer = Buffer.alloc(48);
        buffer.write('wOF2', 0, 4, 'latin1');

        expect(() => parse(buffer)).toThrow(/^WOFF2 require an external decompressor library, see examples at: /);
        expect(() => parse(buffer)).toThrow(
            'https://github.com/opentypejs/opentype.js/issues/183#issuecomment-1147228025'
        );
    });

    test('rejects fonts without TrueType, CFF or CFF2 outlines', () => {
        // Keep all directory entries valid but hide the glyf table so no outline parser can run.
        const buffer = renameTableTag(readFont('Changa-Regular.ttf'), 'glyf', 'ZZZZ');

        expect(() => parse(buffer)).toThrow(/^Font doesn't contain TrueType, CFF or CFF2 outlines\.$/);
    });

    test('throws instead of returning a font for truncated data', () => {
        const truncated = readFont('badfont.otf');
        expect(truncated.length).toBe(4);

        expect(() => parse(truncated)).toThrow();
    });
});

describe('parse options', () => {
    test('honors the lowMemory option by loading glyphs lazily', () => {
        const buffer = readFont('Vibur.woff');
        const eager = parse(Buffer.from(buffer));
        const lazy = parse(Buffer.from(buffer), {lowMemory: true});

        expect(eager._push).toBeNull();
        expect(eager._IndexToUnicodeMap).toBeUndefined();

        expect(typeof lazy._push).toBe('function');
        expect(lazy.numGlyphs).toBe(eager.numGlyphs);
        expect(lazy._IndexToUnicodeMap[36]).toEqual({unicodes: [65]});

        // Nothing loaded yet; reading a glyph triggers the lazy load.
        expect(lazy.glyphs.length).toBe(0);
        expect(Object.keys(lazy.glyphs.glyphs)).toHaveLength(0);
        const lazyGlyph = lazy.glyphs.get(36);
        expect(lazy.glyphs.length).toBe(1);
        expect(Object.keys(lazy.glyphs.glyphs)).toHaveLength(1);
        expect(lazyGlyph.index).toBe(36);
        expect(lazyGlyph.path.commands.length).toBe(42);
        expect(lazyGlyph.path.commands).toEqual(eager.glyphs.get(36).path.commands);
        expect(lazy.charToGlyph('A').index).toBe(36);
    });

    test('parses without an options argument', () => {
        const font = parse(readFont('Changa-Regular.ttf'));

        expect(font.numGlyphs).toBe(790);
    });
});

describe('variable font tables', () => {
    test('parses fvar, avar, gvar, STAT and HVAR tables of a variable TrueType font', () => {
        const font = parse(readFont('Changa-VariableFont_wght.ttf'));

        const axes = font.tables.fvar.axes;
        expect(axes).toHaveLength(1);
        expect(axes[0]).toMatchObject({tag: 'wght', minValue: 200, defaultValue: 200, maxValue: 800});
        expect(font.tables.fvar.instances).toHaveLength(7);
        expect(font.tables.fvar.instances[0].coordinates).toEqual({wght: 200});
        expect(font.tables.fvar.instances[0].name.en).toBe('ExtraLight');

        expect(font.tables.avar.axisSegmentMaps).toHaveLength(1);
        expect(font.tables.gvar).toBeDefined();
        expect(font.tables.gvar.glyphVariations).toBeDefined();
        expect(font.tables.stat.axes.map((axis) => axis.tag)).toEqual(['wght']);
        expect(font.tables.hvar).toBeDefined();
        expect(font.tables.hvar.version).toEqual([1, 0]);
    });

    test('parses an avar table mapping normalized coordinates', () => {
        const font = parse(readFont('TestAVAR.ttf'));

        const mappings = font.tables.avar.axisSegmentMaps[0].axisValueMaps;
        expect(mappings).toEqual([
            {fromCoordinate: -1, toCoordinate: -1},
            {fromCoordinate: -0.5, toCoordinate: 0},
            {fromCoordinate: 0, toCoordinate: 0},
            {fromCoordinate: 0.5, toCoordinate: 0},
            {fromCoordinate: 1, toCoordinate: 1}
        ]);
    });

    test('parses a cvar table together with the cvt table it varies', () => {
        const font = parse(readFont('TestCVARGVAROne.ttf'));

        expect(font.tables.cvt.length).toBe(120);
        expect(font.tables.cvar).toBeDefined();
        expect(font.tables.cvar.version).toEqual([1, 0]);
        expect(font.tables.cvar.headers.length).toBeGreaterThan(0);
        expect(font.tables.cvar.headers[0].privatePoints).toEqual([65, 66, 67, 85, 87, 93]);
    });
});

describe('color font tables', () => {
    test('parses COLR and CPAL and exposes palettes through the palette manager', () => {
        const font = parse(readFont('OpenMojiCOLRv0-subset.otf'));

        expect(font.tables.colr.version).toBe(0);
        expect(font.tables.colr.baseGlyphRecords.length).toBe(8);
        expect(font.tables.colr.layerRecords.length).toBe(57);
        expect(font.tables.colr.baseGlyphRecords[0]).toEqual({
            glyphID: 48,
            firstLayerIndex: 0,
            numLayers: 4
        });

        expect(font.tables.cpal.numPaletteEntries).toBe(35);
        expect(font.tables.cpal.colorRecords).toHaveLength(35);
        expect(font.palettes.cpal()).toBe(font.tables.cpal);

        const palettes = font.palettes.getAll();
        expect(palettes).toHaveLength(1);
        expect(palettes[0]).toHaveLength(35);
        expect(palettes[0][0]).toBe('#00000040');
        expect(font.palettes.get(0)).toHaveLength(35);
    });
});

describe('deprecated loading helpers', () => {
    test('load() reports the deprecation through console.error and returns nothing', () => {
        const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

